    unsigned long long mult = 1;
    switch (*end) {
    case 'g':
    case 'G':
        mult *= 1024;
    case 'm':
    case 'M':
        mult *= 1024;
    case 'k':
    case 'K':
        mult *= 1024;
        end++;
        break;
    }
    if (*end != '\0')
        return 0;
    *out = (size_t)(n * mult);
    return 1;
}
